// PLAICRAFT ATTRACT (#1641) — the demo where the TRAINED NET plays.
//
// The old attract replays `plan()`'s precomputed script: a proof the PLANNER
// can clear the quest, drawn twice (once at plan time, once as keypresses).
// This module drives the same sim LIVE instead: seat 1 (hero) walks the
// reactive expert pilot lane (`decide(gs)` — the exact lane the BC net was
// recorded beside), and seat 2 is `createModelPolicy()` — the shipped
// plaicraft-bc/v1 weights making every movement and swing itself. No plan(),
// no script array: the route is generated by the brains as they sense.
//
// That seat config — pilot hero, net partner — is what scored 8/8 held-out
// wins in the rollout (data/plaicraft/results.json), so the attract sells a
// claim the harness re-proves every run (scripts/netdemocheck.mjs) through
// THIS driver, the same code the browser ticks.
//
// Seeds cycle DEMO_SEEDS — the held-out board the score was made on (mirrors
// HELDOUT_SEEDS in scripts/plaicraft-export.mjs; netdemocheck pins that).
//
// Honesty rules:
// - THE one pad per seat, as everywhere: the sim never learns a model exists.
// - If the policy throws, `advance()` reports failure once and the demo is
//   permanently broken (broken is sticky — no flapping); the shell then falls
//   back to the planner-script replay and stops claiming the net in its
//   caption.
// - The demo makes decisions, never calls step(): the shell owns the sim,
//   the events, the sound and the recording (`doSim(inp, pInp)`).

import { makeGame } from './sim.js'
import { decide } from './planner.js'
import { createModelPolicy } from './model.js'

export const DEMO_SEEDS = [100, 101, 102, 103, 104, 105, 106, 107]

export function createNetDemo(opts = {}) {
    const makePolicy = opts.createPolicy || createModelPolicy
    const pilot = opts.pilot || decide
    const policy = makePolicy()
    let seedAt = 0
    let curSeed = null
    const demo = {
        broken: false, // sticky: once the net errors, the shell keeps the planner replay
        get seed() { return curSeed },
        // fresh demo world, net seated. `seed` pins a board (harness); default
        // advances the held-out cycle.
        newGame(seed) {
            const s = seed != null ? seed : DEMO_SEEDS[seedAt]
            seedAt = (seedAt + 1) % DEMO_SEEDS.length
            curSeed = s
            if (policy.reset) policy.reset()
            const gs = makeGame(s, 'warrior', { topDown: true, partner: true, partnerKey: 'elf' })
            gs.partnerOn = true
            gs.partnerMode = 'model'
            return gs
        },
        // one attract tick: THE two pads for this frame, or null the moment
        // the seat's policy fails (the signal for the shell to fall back).
        advance(gs) {
            if (demo.broken || !gs || gs.end) return null
            try {
                const inp = pilot(gs)
                const p = gs.partner
                const pad = gs.partnerOn && p && !p.down && gs.partnerMode === 'model' ? policy.decide(gs) : null
                return {
                    inp,
                    pInp: pad ? { left: !!pad.left, right: !!pad.right, fwd: !!pad.up, back: !!pad.down, sword: !!pad.a } : null,
                }
            } catch {
                demo.broken = true
                return null
            }
        },
        reset() { seedAt = 0; curSeed = null; demo.broken = false; if (policy.reset) policy.reset() },
    }
    return demo
}
